#include <algorithm>
#include <cstddef>
#include <iostream>
#include <limits>
#include <vector>
class Matrix {
    std::size_t rows_ = 0, cols_ = 0;
    std::vector<int> data_;
public:
    Matrix() = default;
    Matrix(const Matrix&) = default;
    Matrix& operator=(const Matrix&) = delete;
    std::size_t rows() const { return rows_; }
    std::size_t cols() const { return cols_; }
    // Precondizione per gli accessi: r < rows(), c < cols().
    int& operator()(std::size_t r, std::size_t c) {
        return data_[r * cols_ + c];
    }
    const int& operator()(std::size_t r, std::size_t c) const {
        return data_[r * cols_ + c];
    }
    bool resize(std::size_t nr, std::size_t nc, int fill = 0) {
        // Verifica il prodotto prima di calcolarlo.
        if (nc != 0 && nr > data_.max_size() / nc) return false;
        if (nr == rows_ && nc == cols_) return true;
        std::vector<int> next(nr * nc, fill);
        // Preserva coordinate, non il prefisso del buffer lineare.
        for (std::size_t r = 0; r < std::min(rows_, nr); ++r)
            for (std::size_t c = 0; c < std::min(cols_, nc); ++c)
                next[r * nc + c] = (*this)(r, c);
        data_.swap(next); // Commit dopo la preparazione completa.
        rows_ = nr;
        cols_ = nc;
        return true;
    }
    // Precondizione: nessun elemento vale INT_MAX.
    Matrix& operator++() {
        for (int& x : data_) ++x;
        return *this;
    }
    Matrix operator++(int) {
        Matrix previous(*this); // Copia profonda tramite vector.
        ++(*this);
        return previous;
    }
};
void print(const Matrix& m) {
    std::cout << m.rows() << ' ' << m.cols();
    for (std::size_t r = 0; r < m.rows(); ++r)
        for (std::size_t c = 0; c < m.cols(); ++c)
            std::cout << ' ' << m(r, c);
    std::cout << '\n';
}
int main() {
    std::size_t r, c, nr, nc;
    int fill;
    std::cin >> r >> c >> nr >> nc >> fill;
    // Il driver accetta dimensioni piccole: nessun input non limitato.
    if (r > 10 || c > 10 || nr > 10 || nc > 10) return 0;
    Matrix m;
    if (!m.resize(r, c)) return 0;
    int value = 1;
    for (std::size_t i = 0; i < r; ++i)
        for (std::size_t j = 0; j < c; ++j) m(i, j) = value++;
    if (!m.resize(nr, nc, fill)) return 0;
    print(m);
    // Prodotto impossibile: rifiuto senza cambiare lo stato.
    const bool rejected = !m.resize(
        std::numeric_limits<std::size_t>::max(), 2);
    std::cout << rejected << '\n';
    print(m);
}

