#include <iostream>
#include <string>
#include <utility>
template<class Derived>
class Repeatable {
protected:
    // Evita di creare direttamente il solo helper come oggetto pubblico.
    Repeatable() = default;
public:
    std::string apply_twice(const std::string& text) const {
        const auto& op = static_cast<const Derived&>(*this);
        const std::string first = op.apply(text);
        return op.apply(first);
    }
};
class Prefix : public Repeatable<Prefix> {
    std::string prefix_;
public:
    explicit Prefix(std::string prefix) : prefix_(std::move(prefix)) {}
    std::string apply(const std::string& text) const {
        return prefix_ + text;
    }
};
int main() {
    std::string prefix, input;
    std::getline(std::cin, prefix);
    std::getline(std::cin, input);
    const Prefix op(prefix);
    std::cout << '[' << op.apply_twice(input) << "]\n"
              << '[' << input << "]\n";
}

